class ResourcePtr {
    int* ptr;
public:
    ResourcePtr() : ptr(new int[10]) {}
    ~ResourcePtr() { delete[] ptr; }

    // 1. Move Constructor
    ResourcePtr(ResourcePtr&& other) noexcept
        : ptr(other.ptr) {
        other.ptr = nullptr; // Steal resource, neutralize source
    }

    // 2. Move Assignment Operator
    ResourcePtr& operator=(ResourcePtr&& other) noexcept {
        delete[] ptr;
        ptr = other.ptr;
        other.ptr = nullptr;
        return *this;
    }
};

ResourcePtr R1;

// 3. Explicitly convert Lvalue (R1) to Xvalue (rvalue reference)
ResourcePtr R2 = std::move(R1); // Triggers Move Ctor

// 4. Function taking rvalue reference
void sink(ResourcePtr&& temp);
